<?php

namespace Flyo\Test\Wysiwyg;

use Flyo\Wysiwyg\WysiwygNode;
use Nadar\ProseMirror\Node;
use Nadar\ProseMirror\Parser;
use PHPUnit\Framework\TestCase;

/**
 * What a class generated by flyo-generate-types looks like, minus the docblocks.
 */
class PersonCardNode extends WysiwygNode
{
    public const IDENTIFIER = 'person_card';

    public const TITLE = 'Person Card';

    /** @return object{unique_id: string, name: string}|null */
    public function getAttrUser()
    {
        /** @var object{unique_id: string, name: string}|null */
        return $this->attr('user');
    }

    /** @return string|null */
    public function getAttrRole()
    {
        /** @var string|null */
        return $this->attr('role');
    }
}

class WysiwygNodeTest extends TestCase
{
    private const NODE = [
        'type' => 'person_card',
        'attrs' => ['user' => ['unique_id' => 'a1', 'name' => 'Jane'], 'role' => 'Lead'],
        'content' => [['type' => 'paragraph', 'content' => [['type' => 'text', 'text' => 'Hi']]]],
    ];

    private const DOC = ['type' => 'doc', 'content' => [self::NODE]];

    public function testReadsAttributesDecodedToArrays(): void
    {
        $node = PersonCardNode::from(self::NODE);

        $this->assertInstanceOf(\stdClass::class, $node->getAttrUser());
        $this->assertSame('a1', $node->getAttrUser()->unique_id);
        $this->assertSame('Lead', $node->getAttrRole());
        $this->assertSame('person_card', $node->getType());
        $this->assertSame('Person Card', $node->getTitle());
        $this->assertCount(1, $node->getContent());
    }

    public function testReadsAttributesDecodedToObjects(): void
    {
        $decoded = json_decode((string) json_encode(self::NODE), false);
        $this->assertIsObject($decoded);

        $this->assertSame('Jane', PersonCardNode::from($decoded)->getAttrUser()?->name);
    }

    public function testMissingAttributesAreNull(): void
    {
        $node = PersonCardNode::from(['type' => 'person_card']);

        $this->assertNull($node->getAttrUser());
        $this->assertEquals(new \stdClass(), $node->getAttrs());
        $this->assertSame([], $node->getContent());
        $this->assertSame('', $node->renderContent());
    }

    /** A node that was never filled in can carry `[]` instead of `{}`. */
    public function testEmptyAttrsListIsAnEmptyMap(): void
    {
        $node = PersonCardNode::from(['type' => 'person_card', 'attrs' => []]);

        $this->assertNull($node->getAttrRole());
        $this->assertEquals(new \stdClass(), $node->getAttrs());
    }

    public function testRefusesANodeOfAnotherElement(): void
    {
        $this->expectException(\InvalidArgumentException::class);
        $this->expectExceptionMessage('describes nodes of type "person_card", not "info_box"');

        PersonCardNode::from(['type' => 'info_box']);
    }

    public function testRefusesSomethingThatIsNoObject(): void
    {
        $this->expectException(\InvalidArgumentException::class);

        WysiwygNode::from(['a', 'b']);
    }

    public function testParserHandsATypedRendererTheGeneratedClass(): void
    {
        $html = (new Parser())
            ->addNode(
                PersonCardNode::IDENTIFIER,
                fn (PersonCardNode $node): string => '<h3>' . $node->getAttrUser()?->name . '</h3>' . $node->renderContent(),
            )
            ->toHtml(self::DOC);

        $this->assertSame('<h3>Jane</h3><p>Hi</p>', $html);
    }

    public function testParserHandsTheBaseClassAnyElement(): void
    {
        $html = (new Parser())
            ->addNode('person_card', fn (WysiwygNode $node): string => $node->getType() . ':' . $node->getAttrs()->role)
            ->toHtml(self::DOC);

        $this->assertSame('person_card:Lead', $html);
    }

    public function testParserStillHandsANodeToOtherRenderers(): void
    {
        $html = (new Parser())
            ->addNode('person_card', fn (Node $node): string => $node->getAttr('role'))
            ->toHtml(self::DOC);

        $this->assertSame('Lead', $html);
    }

    /** Wiring a class to another node type fails when it renders, instead of rendering nothing. */
    public function testParserRefusesAClassOfAnotherElement(): void
    {
        $this->expectException(\InvalidArgumentException::class);
        $this->expectExceptionMessage('describes nodes of type "person_card", not "info_box"');

        (new Parser())
            ->addNode('info_box', fn (PersonCardNode $node): string => '')
            ->toHtml(['type' => 'doc', 'content' => [['type' => 'info_box']]]);
    }
}
